"""One command creates executed UI records, frozen comparisons, figures and report."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import platform as python_platform

from ..container import Platform
from ..devseed import TENANT, seed
from ..store import RecordStore
from .comparison import compare
from .model import MODEL_VERSION


def write_json(path, value):
    path.write_text(json.dumps(value, indent=2, sort_keys=True, allow_nan=False)+"\n")


def figures(output, transfer, cdmo, comparisons):
    (output/".cache").mkdir(exist_ok=True)
    os.environ.setdefault("XDG_CACHE_HOME", str(output/".cache"))
    os.environ.setdefault("MPLCONFIGDIR", str(output/".matplotlib"))
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    plt.rcParams.update({"font.size": 9, "axes.spines.top": False, "axes.spines.right": False})
    fig, axes = plt.subplots(2, 2, figsize=(11, 7), layout="constrained")
    w = transfer["workspace"]
    for i in [0, 1, w["recommended_index"]]:
        if i is None:
            continue
        o = w["options"][i]
        rows = o["result"]["trajectory"]
        for ax, key, label in zip(axes.flat,
            ["interface_temperature_c", "remaining_ice_kg_per_vial", "sublimation_kg_h", "capacity_margin_kg_h"],
            ["Interface temperature (°C)", "Remaining ice (kg/vial)", "Batch vapor rate (kg/h)", "Vapor capacity margin (kg/h)"]):
            ax.plot([r["time_h"] for r in rows], [r[key] for r in rows], label=o["label"])
            ax.set(xlabel="Primary drying time (h)", ylabel=label)
            ax.grid(alpha=.15)
    axes[0, 0].axhline(-28, color="firebrick", ls="--", lw=1, label="Critical interface temperature")
    axes[1, 1].axhline(0, color="firebrick", ls="--", lw=1)
    axes[0, 0].legend(fontsize=7)
    fig.suptitle("Executed Kv–Rp reconstruction · derated receiving capacity is synthetic")
    for extension in ("png", "svg"):
        fig.savefig(output/f"transfer.{extension}", dpi=160)
    plt.close(fig)
    w = cdmo["workspace"]
    fig, axes = plt.subplots(1, 2, figsize=(11, 4), layout="constrained")
    for o in w["options"]:
        rows = o["result"]["trajectory"]
        axes[0].plot([r["time_h"] for r in rows], [r["interface_temperature_c"] for r in rows], label=o["label"])
        axes[1].plot([r["time_h"] for r in rows], [r["sublimation_kg_h"] for r in rows], label=o["label"])
    observed = w["diagnosis"]["observations"]
    axes[0].scatter([r["time_h"] for r in observed], [r["product_temperature_c"] for r in observed], s=10, color="black", label="Synthetic observations ≤ cutoff")
    axes[0].axhline(-28, color="firebrick", ls="--", lw=1)
    for ax in axes:
        ax.axvline(6, color="black", ls=":"); ax.set_xlabel("Primary drying time (h)"); ax.grid(alpha=.15)
    axes[0].set_ylabel("Interface temperature (°C)")
    axes[1].set_ylabel("Batch vapor rate (kg/h)")
    axes[0].legend(fontsize=7)
    fig.suptitle("CDMO cutoff forecast · model predictions and synthetic observations")
    for extension in ("png", "svg"):
        fig.savefig(output/f"cdmo.{extension}", dpi=160)
    plt.close(fig)
    fig, ax = plt.subplots(figsize=(8, 4), layout="constrained")
    cases = comparisons["cases"]
    ax.bar([c["scenario"] for c in cases], [c["physics_only"]["scores"]["future_temperature_rmse_c"] or 0 for c in cases], color="#0f766e")
    ax.set(ylabel="Future temperature RMSE (°C)", xlabel="Frozen synthetic scenario", title="Physics-only forecast vs independent transient reference\nSynthetic evaluation; no measured AI performance comparison")
    for extension in ("png", "svg"):
        fig.savefig(output/f"comparison.{extension}", dpi=160)
    plt.close(fig)


def report(output, transfer, cdmo, comparisons):
    lines = ["# Executed freeze-drying demonstration", "",
        "Generated by `PYTHONPATH=backend .venv/bin/python -m src.lifesci.lyophilization.demo`. All numbers below come from the saved calculation records.", "",
        "## Scientific source and reproducibility", "",
        "[Vanbillemont et al. (2025)](https://doi.org/10.1186/s41120-025-00115-5) supports a mechanistic reconstruction. Its raw experimental datasets are not publicly available; the supplement contains cake images only. No independent experimental trajectory or numerical digitization is available. Prediction error below is against a synthetic reference, never experimental validation. See [source inventory](../../research/freeze-drying-sources.md).", "",
        "Published: formulation, vial geometry, Kv/Rp regressions, critical temperature and pilot/commercial operating summaries. Reconstructed: constant latent heat/ice conductivity, quasi-steady Fourier frozen-layer conduction, idealized schedules, lognormal variability, receiving derating, ice storage, utilities and synthetic CDMO sensors. Every numerical input is classified with units in the simulation record. No new experimentally estimated or digitized inputs were produced.", "",
        "The source has an omitted exponential in its vapor-pressure equation and a conflicting pilot choked-flow slope. The implementation uses Murphy–Koop exponential vapor pressure and a constant pilot deposition ceiling within the characterized pressure range. It does not silently repair the disputed slope. Commercial experimental transfer used one shelf; the 11,000-vial demonstration is a reconstructed full-load scenario.", "",
        "## Technology transfer", "",
        "| Candidate | Load | Completion h | Critical margin °C | Vapor margin kg/h | Nominally feasible |",
        "|---|---:|---:|---:|---:|---|"]
    for o in transfer["workspace"]["options"]:
        lines.append(f"| {o['label']} | {o['load_vials']} | {o['completion_time_h'] or 0:.2f} | {o['critical_margin_c'] or 0:.2f} | {o['capacity_margin_kg_h'] or 0:.3f} | {o['feasible']} |")
    selected = transfer["workspace"]["recommended_index"]
    if selected is not None:
        u = transfer["workspace"]["options"][selected]["uncertainty"]
        lines.extend(["", f"Selected-candidate uncertainty: {u['samples']} samples, seed {u['seed']}; conditional completion P05/P50/P95 = {u['completion_time_h_p05_p50_p95_conditional_on_completion']} h; {u['not_completed_samples']} samples did not complete; constraint sample frequency {u['constraint_sample_frequency']:.3f}. These are assumed-distribution outcomes, not calibrated risks."])
    lines.extend(["", "Full loading on the derated receiving equipment violates the assumed vapor-handling ceiling. Such imposed-pressure trajectories are diagnostic extrapolations once capacity is exceeded. Bounded changes trade batch size and hold duration; selection maximizes nominal primary-drying throughput, excluding freezing, secondary drying and turnaround.", "", "![Transfer plots](transfer.png)", "", "## CDMO operation", "",
        "At the fixed 6 h evidence cutoff, a temperature-only fit evaluates three distinguishable explanations:", "",
        "| Hypothesis | Estimated modifier | Temperature RMSE °C | Identifiable |", "|---|---:|---:|---|"])
    for h in cdmo["workspace"]["diagnosis"]["hypotheses"]:
        estimate = f"{h['estimate']:.3f}" if h["estimate"] is not None else "withheld"
        lines.append(f"| {h['hypothesis']} | {estimate} | {h['temperature_rmse_c']:.3f} | {h['identifiable']} |")
    lines.extend(["", "The interactive CDMO illustration has a known planned shelf step to −14°C at 8 h (editable in the UI), chosen to make the future-control comparison inspectable. The four frozen evaluation cases retain their original −18°C step; no benchmark scenario was changed to improve a score.", "",
                  "| CDMO candidate | Completion h | Critical margin °C | Nominal feasible |", "|---|---:|---:|---|"])
    for o in cdmo["workspace"]["options"]:
        lines.append(f"| {o['label']} | {o['completion_time_h'] or 0:.2f} | {o['critical_margin_c'] or 0:.2f} | {o['feasible']} |")
    lines.extend(["", "Heat transfer and resistance compensate in early temperature data. Reduced vapor capacity is unidentifiable with prescribed pressure and is not ruled out. Pair gravimetric batch mass loss with center/edge thermometry and independent pressure-control characterization. Changes begin at the cutoff; prior thermal excursions block a rescue recommendation.", "", "![CDMO forecasts](cdmo.png)", "",
        "## Frozen comparison results", "", "Protocol and hidden targets were written and hashed before reference and agent execution. Both AI arms use the existing PrimeInvestigationAdapter, the same visible packet and model route, 32 tool calls, 120 s and a $1 reservation. Existing evidence, historical comparisons, analytics and Python calculations remain available; A may write its own numerical simulator. B additionally receives registered process-model adapters. No completed agent response is replaced with a canned result.", "",
        "| Scenario | Physics temp RMSE °C | Coverage | Completion absolute error h | Thermal detection | Vapor detection | Reference intervention feasible | A | B |", "|---|---:|---:|---:|---|---|---|---|---|"])
    for c in comparisons["cases"]:
        s, intervention = c["physics_only"]["scores"], c["physics_only"]["intervention"]
        err = f"{s['completion_absolute_error_h']:.2f}" if s["completion_absolute_error_h"] is not None else "censored"
        agents = [a["adapter_result"]["status"] for a in c["agent_arms"]]
        lines.append(f"| {c['scenario']} | {s['future_temperature_rmse_c']:.3f} | {s['coverage']:.2f} | {err} | {s['constraint_detection']['critical_temperature']['detection']} | {s['constraint_detection']['vapor_capacity']['detection']} | {intervention['feasible_in_reference'] if intervention else 'none'} | {agents[0]} | {agents[1]} |")
    lines.extend(["", "TP/FP/FN/TN are evaluated separately for temperature and vapor constraints. The reference has finite heat capacity, two vial populations and pressure response; the tool is quasi-steady and represents one vial. Shared constitutive laws remain a limitation. Forecast error uses overlapping active-primary-drying times only; coverage is reported to expose endpoint censoring. Thermal detection compares the representative-vial prediction with the hottest active reference population.", "",
        "![Synthetic reference comparison](comparison.png)", "", "### Agent attempts and resource measurements", ""])
    lines.extend(["The initial reference version imposed a −40°C initial node without thermal equilibrium and produced startup capacity excursions in every scenario. Its full outputs are preserved in [initial-reference-audit](../initial-reference-audit/report.md). The corrected equilibrium-start version was frozen and rerun with the same hidden shifts, cutoffs, candidate bounds and scoring rules. The retained missed warnings are not tuned away.", ""])
    for c in comparisons["cases"]:
        for a in c["agent_arms"]:
            issues = "; ".join(a["adapter_result"].get("issues", []))
            lines.append(f"- {c['scenario']} / {a['arm']}: `{a['adapter_result']['status']}`, {a['runtime_seconds']:.4f} s adapter runtime. {issues}")
    lines.extend(["", "No route was automatically qualified to obtain a response. Unavailable runs have null AI scientific scores and no measured AI uplift. Persisted gateway records retain status, issues, configuration and actual spend; zero spend for a routing rejection is not a measured successful inference cost. Human review effort is unavailable. Existing deterministic concern analytics were executed separately and saved; they are not described as AI performance.", "", "### Warning timing and intervention checks", ""])
    for c in comparisons["cases"]:
        s = c["physics_only"]["scores"]
        lines.append(f"- {c['scenario']}: lead times (h): thermal={s['constraint_detection']['critical_temperature']['warning_lead_time_h']}, vapor={s['constraint_detection']['vapor_capacity']['warning_lead_time_h']}; intervention={json.dumps(c['physics_only']['intervention'], sort_keys=True)}. Physics runtime {c['physics_only']['runtime_seconds']:.2f} s; inference cost $0.")
    lines.extend(["", "## Limitations and next experiments", "", "This is an unqualified engineering demonstration. It predicts neither final residual moisture, potency, release suitability, energy nor commercial yield. Monte Carlo frequencies are conditional outcomes under assumed distributions, not calibrated real-world risks. Eight or sixteen samples cannot estimate rare failures. Full commercial-scale experimental transfer, facility utilities and vapor capacity require characterization. The operations estimator is conditional replay with fixed fitted parameters, not validated online state estimation. Ambiguous explanations and structurally missing capacity dynamics can produce missed warnings and infeasible recommendations in the independent reference; these failures are preserved.", "", "Next: obtain raw pilot/commercial traces and exact loads; resolve the pilot slope with authors; characterize edge/center Kv, product-specific Rp and capacity; pre-register an independent holdout; execute the instrumented verification plan with assigned MSAT and QA reviewers. Temperature <−28°C, pressure-control headroom, independently verified endpoint and prespecified engineering error tolerances require reviewer approval. Final product testing remains separate.", "", "## Detailed article outline", "", "1. **Published context:** primary drying physics and the authors’ pilot-to-commercial case, with exact scope of experimental verification.", "2. **Published evidence boundary:** acquisition, unavailable raw data, supplement contents, parameter transcription, source equation/conflict handling and LyoPRONTO licensing.", "3. **Our implemented reconstruction:** SI balances, solver/event handling, frozen-layer conduction approximation, schedules, applicability limits and provenance records.", "4. **Our measured transfer calculation:** direct transfer, receiving derating, bounded loading/temperature comparison, throughput trade-offs, sampling intervals and proposed verification.", "5. **Our measured CDMO calculation:** evidence cutoff, ambiguous Kv/Rp fits, capacity non-identifiability, no-change and intervention trajectories, no rescue claim.", "6. **Our measured comparison:** frozen protocol, independent synthetic reference, executed existing-agent attempts, unavailable AI scores, false alarms/misses, lead times and intervention failures.", "7. **Our integration evidence:** authenticated API, permission checks, reviewed proposals, source revisions, invalidation, tests and browser checks; no production qualification claim.", "8. **Future hypotheses:** calibrated early warnings, improved transfer efficiency and reduced review effort; each needs prospective measurement rather than inference from this demo.", "9. **Next experiments and acceptance:** obtain holdouts, characterize equipment/formulation, assign reviewers and evaluate endpoint, thermal margins and final product separately.", ""])
    (output/"report.md").write_text("\n".join(lines))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=Path("docs/process-simulation/artifacts"))
    args = parser.parse_args()
    output = args.output.resolve(); output.mkdir(parents=True, exist_ok=True)
    protocol = json.loads(Path(__file__).with_name("protocol.json").read_text())
    write_json(output/"protocol.json", protocol)
    p = Platform(RecordStore(), providers=None)
    seed(p)
    ctx = p.identity.context_for(TENANT, "priya")
    print("Executing shared-model transfer and CDMO workflows…", flush=True)
    transfer = p.process_models.run(ctx, samples=16)
    cdmo = p.process_models.run(ctx, audience="cdmo_operation", samples=16)
    proposal = p.process_models.propose(ctx, transfer["id"], owner_id="priya")
    write_json(output/"transfer.json", transfer)
    write_json(output/"cdmo.json", cdmo)
    write_json(output/"transfer-proposal.json", proposal)
    print("Freezing targets and executing independent reference / existing-agent attempts…", flush=True)
    comparison = compare(p, ctx, output, protocol)
    write_json(output/"comparison.json", comparison)
    write_json(output/"environment.json", {"python": python_platform.python_version(), "model_version": MODEL_VERSION,
                                         "solver": transfer["workspace"]["options"][0]["result"]["solver"],
                                         "source_archive_manifest_sha256": hashlib.sha256(Path("docs/research/freeze-drying-sources/manifest.json").read_bytes()).hexdigest() if Path("docs/research/freeze-drying-sources/manifest.json").exists() else None})
    print("Rendering executed plots and report…", flush=True)
    figures(output, transfer, cdmo, comparison)
    report(output, transfer, cdmo, comparison)
    print(output/"report.md", flush=True)


if __name__ == "__main__":
    main()
